#!/usr/bin/env bash
#
# Server-side deployment script. The GitLab deploy job scp's this next to the
# generated .env and runs it over ssh:
#
#     ssh user@host "bash /home/<user>/lol/<stack>/deploy.sh"
#
# Everything docker-related happens HERE rather than inside an ssh "..." string,
# so no quoting has to survive a round trip through the CI shell.
#
# Expects, in the same directory:
#   .env             generated by CI — image names, IMAGE_TAG, secrets,
#                    COMPOSE_PROJECT_NAME, STACK
#   .registry.env    generated by CI — a read_registry Deploy Token
#   docker-compose.prod.yml
# and a sibling ../edge/ directory holding the Caddy stack.
#
# Safe to re-run: every step is idempotent. Named volumes are not used — all
# state lives in ./data/, which is never touched here.

set -euo pipefail

cd "$(dirname "$0")"
APP_DIR="$PWD"
EDGE_DIR="$(cd .. && pwd)/edge"
SECRETS_FILE="$APP_DIR/.secrets.env"

# -----------------------------------------------------------------------------
# Self-managed secrets
# -----------------------------------------------------------------------------
# These six have no external issuer — they just need to be random and stable —
# so there is nothing to be gained by making a human paste them into GitLab.
# Generated here on first deploy, persisted in .secrets.env (chmod 600), reused
# verbatim on every later deploy. A CI variable of the same name still wins
# (delivered in .overrides.env), so any of them can be pinned or rotated later.
#
# .secrets.env IS THE CROWN JEWELS. Losing it means: the app can no longer
# authenticate to its own database, every session is invalidated, and — because
# PII_ENCRYPTION_KEY encrypts OAuth tokens and verification state at rest —
# previously stored PII becomes undecryptable. Back it up with ./data.
MANAGED_SECRETS="POSTGRES_PASSWORD APP_DB_PASSWORD JWT_SECRET PII_ENCRYPTION_KEY BOT_SERVICE_TOKEN LIFECYCLE_SERVICE_TOKEN"

# URL-safe base64, '=' stripped: safe inside a compose .env and inside a DSN.
_gen_token() { head -c 32 /dev/urandom | base64 | tr -d '\n=' | tr '+/' '-_'; }
# Fernet requires urlsafe_b64encode(32 bytes) EXACTLY — keep the '=' padding.
_gen_fernet() { head -c 32 /dev/urandom | base64 | tr -d '\n' | tr '+/' '-_'; }

_read_key() { sed -n "s/^$1=//p" "$2" 2>/dev/null | head -1; }

touch "$SECRETS_FILE"
chmod 600 "$SECRETS_FILE"
[ -f .overrides.env ] || : > .overrides.env

for _key in $MANAGED_SECRETS; do
    _value="$(_read_key "$_key" .overrides.env)"
    if [ -n "$_value" ]; then
        echo "--- $_key: using the CI-provided override"
    else
        _value="$(_read_key "$_key" "$SECRETS_FILE")"
        if [ -z "$_value" ]; then
            case "$_key" in
                PII_ENCRYPTION_KEY) _value="$(_gen_fernet)" ;;
                *) _value="$(_gen_token)" ;;
            esac
            printf '%s=%s\n' "$_key" "$_value" >> "$SECRETS_FILE"
            echo "--- $_key: generated (first deploy)"
        fi
    fi
    printf '%s=%s\n' "$_key" "$_value" >> ./.env
done

# The DSNs embed the passwords resolved above, so they are composed here rather
# than in CI. Owner DSN = migrations (a superuser BYPASSES RLS); app_rw DSN =
# the request path, where FORCE-RLS actually binds.
_pg_pw="$(_read_key POSTGRES_PASSWORD ./.env)"
_app_pw="$(_read_key APP_DB_PASSWORD ./.env)"
{
    echo "DATABASE_URL=postgresql+asyncpg://lol:${_pg_pw}@postgres:5432/lol"
    echo "APP_DATABASE_URL=postgresql+asyncpg://app_rw:${_app_pw}@postgres:5432/lol"
} >> ./.env

# Values come from a compose .env: no spaces, no '#', no '$' in secrets.
set -a
# shellcheck disable=SC1091
. ./.env
# shellcheck disable=SC1091
. ./.registry.env
set +a

COMPOSE="docker compose -f docker-compose.prod.yml"

echo "=== deploying ${COMPOSE_PROJECT_NAME} (stack=${STACK}) at tag ${IMAGE_TAG}"

# --- shared edge network ------------------------------------------------------
# Both the app stack and the Caddy stack attach to it; created once, kept forever.
docker network inspect lol-edge >/dev/null 2>&1 || docker network create lol-edge

# --- registry login -----------------------------------------------------------
# A Deploy Token, NOT the CI job token: this login is persisted in
# ~/.docker/config.json so `docker compose up -d` still pulls after a reboot,
# long after the pipeline that deployed it has finished.
echo "$REGISTRY_PASSWORD" | docker login -u "$REGISTRY_USER" --password-stdin "$REGISTRY_HOST"

# --- application stack --------------------------------------------------------
echo "--- pulling images"
$COMPOSE pull --quiet

echo "--- starting containers"
# --remove-orphans drops containers left behind by a renamed/removed service.
$COMPOSE up -d --remove-orphans

echo "--- waiting for the backend container"
for _ in $(seq 1 30); do
    state="$(docker inspect -f '{{.State.Running}}' "lol-${STACK}-backend" 2>/dev/null || echo false)"
    [ "$state" = "true" ] && break
    sleep 2
done
if [ "$(docker inspect -f '{{.State.Running}}' "lol-${STACK}-backend" 2>/dev/null || echo false)" != "true" ]; then
    echo "ERROR: lol-${STACK}-backend did not start." >&2
    $COMPOSE logs --tail 50 backend >&2 || true
    exit 1
fi

echo "--- migrations"
# Picks fresh-DB bootstrap vs incremental upgrade, and rotates the app_rw
# password off the migration's dev default. See services/backend/scripts/migrate.sh.
$COMPOSE exec -T backend /app/scripts/migrate.sh

# --- edge (Caddy) -------------------------------------------------------------
echo "--- edge proxy"
cd "$EDGE_DIR"
docker compose -f docker-compose.edge.yml up -d
# Reload rather than restart: picks up this stack's new sites/<stack>.caddy
# without dropping live connections or re-running ACME.
if docker exec lol-caddy caddy reload --config /etc/caddy/Caddyfile --adapter caddyfile; then
    echo "caddy reloaded"
else
    echo "caddy reload failed — restarting the container" >&2
    docker compose -f docker-compose.edge.yml restart caddy
fi

# --- housekeeping -------------------------------------------------------------
cd "$APP_DIR"
docker image prune -f >/dev/null

echo "=== deployed:"
$COMPOSE ps
